import{_ as p,a0 as a,w as i,s as S,I as t,x as s,a1 as o,A as n,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const N=JSON.parse('{"title":"如何通過反向 SSH 隧道訪問 NAT 後面的 Linux 服務器 | LCTT x X-CMD","titleTemplate":false,"description":"如何通過反向 SSH 隧道訪問 NAT 後面的 Linux 服務器 | LCTT (201508) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何通過反向 SSH 隧道訪問 NAT 後面的 Linux 服務器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何通過反向 SSH 隧道訪問 NAT 後面的 Linux 服務器 | LCTT (201508) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201508/20150504 How to access a Linux server behind NAT via reverse SSH tunnel","title":"如何通過反向 SSH 隧道訪問 NAT 後面的 Linux 服務器","tag":"201508","desc":""},"relativePath":"201508/20150504 How to access a Linux server behind NAT via reverse SSH tunnel.md","filePath":"[post].md"}'),d={name:"201508/20150504 How to access a Linux server behind NAT via reverse SSH tunnel.md"};function u(h,e,H,m,x,T){const r=a("Link");return i(),S("div",null,[e[24]||(e[24]=t("h1",{id:"如何通過反向-ssh-隧道訪問-nat-後面的-linux-服務器",tabindex:"-1"},[s("如何通過反向 SSH 隧道訪問 NAT 後面的 Linux 服務器 "),t("a",{class:"header-anchor",href:"#如何通過反向-ssh-隧道訪問-nat-後面的-linux-服務器","aria-label":"Permalink to “如何通過反向 SSH 隧道訪問 NAT 後面的 Linux 服務器”"},"​")],-1)),e[25]||(e[25]=t("p",null,"你在家裏運行着一台 Linux 服務器，它放在一個 NAT 路由器或者限制性防火牆後面。現在你想在外出時用 SSH 登錄到這台服務器。你如何才能做到呢？SSH 端口轉發當然是一種選擇。但是，如果你需要處理多級嵌套的 NAT 環境，端口轉發可能會變得非常棘手。另外，在多種 ISP 特定條件下可能會受到干擾，例如阻塞轉發端口的限制性 ISP 防火牆、或者在用户間共享 IPv4 地址的運營商級 NAT。",-1)),e[26]||(e[26]=t("h3",{id:"什麼是反向-ssh-隧道",tabindex:"-1"},[s("什麼是反向 SSH 隧道？ "),t("a",{class:"header-anchor",href:"#什麼是反向-ssh-隧道","aria-label":"Permalink to “什麼是反向 SSH 隧道？”"},"​")],-1)),t("p",null,[e[1]||(e[1]=s("SSH 端口轉發的一種替代方案是 ",-1)),e[2]||(e[2]=t("strong",null,"反向 SSH 隧道",-1)),e[3]||(e[3]=s("。反向 SSH 隧道的概念非常簡單。使用這種方案，在你的受限的家庭網絡之外你需要另一台主機（所謂的“中繼主機”），你能從當前所在地通過 SSH 登錄到它。你可以用有公網 IP 地址的 ",-1)),o(r,{href:"http://xmodulo.com/go/digitalocean"},{default:n(()=>[...e[0]||(e[0]=[s("VPS 實例",-1)])]),_:1}),e[4]||(e[4]=s(" 配置一箇中繼主機。然後要做的就是從你的家庭網絡服務器中建立一個到公網中繼主機的永久 SSH 隧道。有了這個隧道，你就可以從中繼主機中連接“回”家庭服務器（這就是為什麼稱之為 “反向” 隧道）。不管你在哪裏、你的家庭網絡中的 NAT 或 防火牆限制多麼嚴格，只要你可以訪問中繼主機，你就可以連接到家庭服務器。",-1))]),e[27]||(e[27]=l(`<p><img src="https://farm8.staticflickr.com/7742/17162647378_c7d9f10de8_b.jpg" alt=""></p><h3 id="在-linux-上設置反向-ssh-隧道" tabindex="-1">在 Linux 上設置反向 SSH 隧道 <a class="header-anchor" href="#在-linux-上設置反向-ssh-隧道" aria-label="Permalink to “在 Linux 上設置反向 SSH 隧道”">​</a></h3><p>讓我們來看看怎樣創建和使用反向 SSH 隧道。我們做如下假設：我們會設置一個從家庭服務器（homeserver）到中繼服務器（relayserver）的反向 SSH 隧道，然後我們可以通過中繼服務器從客户端計算機（clientcomputer） SSH 登錄到家庭服務器。本例中的<strong>中繼服務器</strong> 的公網 IP 地址是 1.1.1.1。</p><p>在家庭服務器上，按照以下方式打開一個到中繼服務器的 SSH 連接。</p><pre><code>homeserver~$ ssh -fN -R 10022:localhost:22 relayserver_user@1.1.1.1
</code></pre><p>這裏端口 10022 是任何你可以使用的端口數字。只需要確保中繼服務器上不會有其它程序使用這個端口。</p><p>“-R 10022:localhost:22” 選項定義了一個反向隧道。它轉發中繼服務器 10022 端口的流量到家庭服務器的 22 號端口。</p><p>用 “-fN” 選項，當你成功通過 SSH 服務器驗證時 SSH 會進入後台運行。當你不想在遠程 SSH 服務器執行任何命令，就像我們的例子中只想轉發端口的時候非常有用。</p><p>運行上面的命令之後，你就會回到家庭主機的命令列提示框中。</p><p>登錄到中繼服務器，確認其 127.0.0.1:10022 綁定到了 sshd。如果是的話就表示已經正確設置了反向隧道。</p><pre><code>relayserver~$ sudo netstat -nap | grep 10022
</code></pre><hr><pre><code>tcp      0    0 127.0.0.1:10022          0.0.0.0:*               LISTEN      8493/sshd           
</code></pre><p>現在就可以從任何其它計算機（客户端計算機）登錄到中繼服務器，然後按照下面的方法訪問家庭服務器。</p><pre><code>relayserver~$ ssh -p 10022 homeserver_user@localhost
</code></pre><p>需要注意的一點是你在上面為localhost輸入的 SSH 登錄/密碼應該是家庭服務器的，而不是中繼服務器的，因為你是通過隧道的本地端點登錄到家庭服務器，因此不要錯誤輸入中繼服務器的登錄/密碼。成功登錄後，你就在家庭服務器上了。</p><h3 id="通過反向-ssh-隧道直接連接到網絡地址變換後的服務器" tabindex="-1">通過反向 SSH 隧道直接連接到網絡地址變換後的服務器 <a class="header-anchor" href="#通過反向-ssh-隧道直接連接到網絡地址變換後的服務器" aria-label="Permalink to “通過反向 SSH 隧道直接連接到網絡地址變換後的服務器”">​</a></h3><p>上面的方法允許你訪問 NAT 後面的 <strong>家庭服務器</strong>，但你需要登錄兩次：首先登錄到 <strong>中繼服務器</strong>，然後再登錄到<strong>家庭服務器</strong>。這是因為中繼服務器上 SSH 隧道的端點綁定到了迴環地址（127.0.0.1）。</p><p>事實上，有一種方法可以只需要登錄到中繼服務器就能直接訪問NAT之後的家庭服務器。要做到這點，你需要讓中繼服務器上的 sshd 不僅轉發迴環地址上的端口，還要轉發外部主機的端口。這通過指定中繼服務器上運行的 sshd 的 <strong>GatewayPorts</strong> 實現。</p><p>打開<strong>中繼服務器</strong>的 /etc/ssh/sshd_conf 並添加下面的行。</p><pre><code>relayserver~$ vi /etc/ssh/sshd_conf
</code></pre><hr><pre><code>GatewayPorts clientspecified
</code></pre><p>重啓 sshd。</p><p>基於 Debian 的系統：</p><pre><code>relayserver~$ sudo /etc/init.d/ssh restart
</code></pre><p>基於紅帽的系統：</p><pre><code>relayserver~$ sudo systemctl restart sshd
</code></pre><p>現在在家庭服務器中按照下面方式初始化一個反向 SSH 隧道。</p><pre><code>homeserver~$ ssh -fN -R 1.1.1.1:10022:localhost:22 relayserver_user@1.1.1.1
</code></pre><p>登錄到中繼服務器然後用 netstat 命令確認成功建立的一個反向 SSH 隧道。</p><pre><code>relayserver~$ sudo netstat -nap | grep 10022
</code></pre><hr><pre><code>tcp      0      0 1.1.1.1:10022     0.0.0.0:*           LISTEN      1538/sshd: dev  
</code></pre><p>不像之前的情況，現在隧道的端點是 1.1.1.1:10022（中繼服務器的公網 IP 地址），而不是 127.0.0.1:10022。這就意味着從外部主機可以訪問隧道的另一端。</p><p>現在在任何其它計算機（客户端計算機），輸入以下命令訪問網絡地址變換之後的家庭服務器。</p><pre><code>clientcomputer~$ ssh -p 10022 homeserver_user@1.1.1.1
</code></pre><p>在上面的命令中，1.1.1.1 是中繼服務器的公共 IP 地址，homeserver_user必須是家庭服務器上的用户賬户。這是因為你真正登錄到的主機是家庭服務器，而不是中繼服務器。後者只是中繼你的 SSH 流量到家庭服務器。</p><h3 id="在-linux-上設置一個永久反向-ssh-隧道" tabindex="-1">在 Linux 上設置一個永久反向 SSH 隧道 <a class="header-anchor" href="#在-linux-上設置一個永久反向-ssh-隧道" aria-label="Permalink to “在 Linux 上設置一個永久反向 SSH 隧道”">​</a></h3><p>現在你已經明白了怎樣創建一個反向 SSH 隧道，然後把隧道設置為 “永久”，這樣隧道啓動後就會一直運行（不管臨時的網絡擁塞、SSH 超時、中繼主機重啓，等等）。畢竟，如果隧道不是一直有效，你就不能可靠的登錄到你的家庭服務器。</p><p>對於永久隧道，我打算使用一個叫 autossh 的工具。正如名字暗示的，這個程序可以讓你的 SSH 會話無論因為什麼原因中斷都會自動重連。因此對於保持一個反向 SSH 隧道非常有用。</p>`,41)),t("p",null,[e[6]||(e[6]=s("第一步，我們要設置從家庭服務器到中繼服務器的",-1)),o(r,{href:"https://linux.cn/article-5444-1.html"},{default:n(()=>[...e[5]||(e[5]=[s("無密碼 SSH 登錄",-1)])]),_:1}),e[7]||(e[7]=s("。這樣的話，autossh 可以不需要用户干預就能重啓一個損壞的反向 SSH 隧道。",-1))]),t("p",null,[e[9]||(e[9]=s("下一步，在建立隧道的家庭服務器上",-1)),o(r,{href:"https://linux.cn/article-5459-1.html"},{default:n(()=>[...e[8]||(e[8]=[s("安裝 autossh",-1)])]),_:1}),e[10]||(e[10]=s("。",-1))]),e[28]||(e[28]=l(`<p>在家庭服務器上，用下面的參數運行 autossh 來創建一個連接到中繼服務器的永久 SSH 隧道。</p><pre><code>homeserver~$ autossh -M 10900 -fN -o &quot;PubkeyAuthentication=yes&quot; -o &quot;StrictHostKeyChecking=false&quot; -o &quot;PasswordAuthentication=no&quot; -o &quot;ServerAliveInterval 60&quot; -o &quot;ServerAliveCountMax 3&quot; -R 1.1.1.1:10022:localhost:22 relayserver_user@1.1.1.1
</code></pre><p>“-M 10900” 選項指定中繼服務器上的監視端口，用於交換監視 SSH 會話的測試數據。中繼服務器上的其它程序不能使用這個端口。</p><p>“-fN” 選項傳遞給 ssh 命令，讓 SSH 隧道在後台運行。</p><p>“-o XXXX” 選項讓 ssh：</p><ul><li>使用密鑰驗證，而不是密碼驗證。</li><li>自動接受（未知）SSH 主機密鑰。</li><li>每 60 秒交換 keep-alive 消息。</li><li>沒有收到任何響應時最多發送 3 條 keep-alive 消息。</li></ul><p>其餘 SSH 隧道相關的選項和之前介紹的一樣。</p><p>如果你想系統啓動時自動運行 SSH 隧道，你可以將上面的 autossh 命令添加到 /etc/rc.local。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>在這篇博文中，我介紹了你如何能從外部通過反向 SSH 隧道訪問限制性防火牆或 NAT 網關之後的 Linux 服務器。這裏我介紹了家庭網絡中的一個使用事例，但在企業網絡中使用時你尤其要小心。這樣的一個隧道可能被視為違反公司政策，因為它繞過了企業的防火牆並把企業網絡暴露給外部攻擊。這很可能被誤用或者濫用。因此在使用之前一定要記住它的作用。</p><hr>`,11)),t("p",null,[e[12]||(e[12]=s("via: ",-1)),o(r,{href:"http://xmodulo.com/access-linux-server-behind-nat-reverse-ssh-tunnel.html"},{default:n(()=>[...e[11]||(e[11]=[s("http://xmodulo.com/access-linux-server-behind-nat-reverse-ssh-tunnel.html",-1)])]),_:1})]),t("p",null,[e[16]||(e[16]=s("作者：",-1)),o(r,{href:"http://xmodulo.com/author/nanni"},{default:n(()=>[...e[13]||(e[13]=[s("Dan Nanni",-1)])]),_:1}),e[17]||(e[17]=s(" 譯者：",-1)),o(r,{href:"https://github.com/ictlyh"},{default:n(()=>[...e[14]||(e[14]=[s("ictlyh",-1)])]),_:1}),e[18]||(e[18]=s(" 校對：",-1)),o(r,{href:"https://github.com/wxy"},{default:n(()=>[...e[15]||(e[15]=[s("wxy",-1)])]),_:1})]),t("p",null,[e[21]||(e[21]=s("本文由 ",-1)),o(r,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[19]||(e[19]=[s("LCTT",-1)])]),_:1}),e[22]||(e[22]=s(" 原創翻譯，",-1)),o(r,{href:"http://linux.cn/"},{default:n(()=>[...e[20]||(e[20]=[s("Linux中國",-1)])]),_:1}),e[23]||(e[23]=s(" 榮譽推出",-1))])])}const A=p(d,[["render",u]]);export{N as __pageData,A as default};
